const k = ($input.first().json.keys || [])[0];
const tr = k && (k.translations || []).find(t => t.modified_by_email === 'qrcodelocalization@gmail.com');
if (!tr) throw new Error('uid not found: ' + JSON.stringify($input.first().json).slice(0,500));
const uid = tr.modified_by;
const out = [];
const start = new Date('2025-09-25T00:00:00Z'); const end = new Date('2026-09-24T00:00:00Z');
const EV = ['translation.updated','translations.updated'];
for (let d = new Date(start); d <= end; d = new Date(d.getTime() + 7*86400000)) {
  const f = d.toISOString().slice(0,10);
  const tEnd = new Date(Math.min(d.getTime() + 6*86400000, end.getTime())).toISOString().slice(0,10);
  for (const e of EV) out.push({ json: { uid, e, from: f, to: tEnd, url: 'https://api.lokalise.com/v1/audit-logs?limit=1000&user_id=' + uid + '&event_type=' + e + '&date_from=' + f + '&date_to=' + tEnd } });
}
return out;

const P = '9933660066825e9a8005c8.58526829';
const reqs = $('Build audit requests').all();
const res = $input.all();
const summary = []; const ev = []; const seen = new Set();
res.forEach((it, i) => { const b = it.json; const q = reqs[i].json;
  const arr = Array.isArray(b.data) ? b.data : null; let inProj = 0;
  for (const e of (arr || [])) {
    const uid = (e.metadata && e.metadata.uid); if (uid && seen.has(uid)) continue; if (uid) seen.add(uid);
    const pr = (e.enrichments || []).find(x => x.name === 'project');
    if (!pr || !pr.data || pr.data.id !== P) continue; inProj++;
    const d = (e.unmapped && e.unmapped.data) || {}; const api = e.unmapped && e.unmapped.api_call;
    if (d.lang_id || d.key_id) ev.push({ t: e.time, kid: d.key_id, lang: d.lang_iso, lid: d.lang_id, o: d.old_translation, n: d.new_translation, bulk: 0, api });
    else for (const x of (d.translations || [])) ev.push({ t: e.time, kid: x.key && x.key.id, lid: x.language && x.language.id, o: x.previous_value, n: x.value, bulk: 1, api });
  }
  if (!arr || b.has_more || inProj) summary.push({ e: q.e, from: q.from, n: arr ? arr.length : -1, more: b.has_more, inProj, err: arr ? null : JSON.stringify(b).slice(0,200) });
});
return [{ json: { uid: reqs[0].json.uid, requests: reqs.length, summary, events: ev } }];
